using Microsoft::WRL::ComPtr;
static void check(HRESULT h,const char* what){if(FAILED(h)){char b[256];sprintf_s(b,"%s failed HRESULT=0x%08X",what,(unsigned)h);throw std::runtime_error(b);}}
static void note(const char* what,HRESULT h){printf("HRESULT %-48s 0x%08X %s\n",what,(unsigned)h,SUCCEEDED(h)?"OK":"FAIL");}
static double qpc(){LARGE_INTEGER x,f;QueryPerformanceCounter(&x);QueryPerformanceFrequency(&f);return (double)x.QuadPart/(double)f.QuadPart;}
static uint32_t expected(uint32_t index,uint32_t seed,uint32_t iters){uint32_t v=index^seed;for(uint32_t i=0;i<iters;++i){v^=v>>13;v*=0x85ebca6b;v^=v<<7;v+=(i^index)*0xc2b2ae35;}return v;}
struct Gpu {
 UINT index=0; DXGI_ADAPTER_DESC1 desc{}; ComPtr<IDXGIAdapter1> adapter; ComPtr<ID3D12Device> dev; ComPtr<ID3D12CommandQueue> queue; ComPtr<ID3D12CommandAllocator> alloc; ComPtr<ID3D12GraphicsCommandList> list; ComPtr<ID3D12Fence> fence; HANDLE eventHandle=nullptr; UINT64 fv=0; double submitTime=0;
 ComPtr<ID3D12RootSignature> root; ComPtr<ID3D12PipelineState> pso; ComPtr<ID3D12DescriptorHeap> uavHeap; UINT descInc=0; ComPtr<ID3D12Resource> output,readback;
 ~Gpu(){if(eventHandle)CloseHandle(eventHandle);}
 void init(UINT i,IDXGIAdapter1* a,ID3DBlob* shader,UINT maxCount){index=i;adapter=a;adapter->GetDesc1(&desc);check(D3D12CreateDevice(adapter.Get(),D3D_FEATURE_LEVEL_11_0,IID_PPV_ARGS(&dev)),"D3D12CreateDevice");D3D12_COMMAND_QUEUE_DESC q{};q.Type=D3D12_COMMAND_LIST_TYPE_COMPUTE;check(dev->CreateCommandQueue(&q,IID_PPV_ARGS(&queue)),"Create compute queue");check(dev->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_COMPUTE,IID_PPV_ARGS(&alloc)),"Create command allocator");check(dev->CreateCommandList(0,D3D12_COMMAND_LIST_TYPE_COMPUTE,alloc.Get(),nullptr,IID_PPV_ARGS(&list)),"Create command list");check(list->Close(),"Close initial list");check(dev->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(&fence)),"Create local fence");eventHandle=CreateEventW(nullptr,TRUE,FALSE,nullptr);if(!eventHandle)throw std::runtime_error("CreateEvent failed");
  D3D12_DESCRIPTOR_RANGE range{};range.RangeType=D3D12_DESCRIPTOR_RANGE_TYPE_UAV;range.NumDescriptors=1;range.BaseShaderRegister=0;range.RegisterSpace=0;range.OffsetInDescriptorsFromTableStart=0;
  D3D12_ROOT_PARAMETER rp[2]{};rp[0].ParameterType=D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;rp[0].Constants={0,0,4};rp[0].ShaderVisibility=D3D12_SHADER_VISIBILITY_ALL;rp[1].ParameterType=D3D12_ROOT_PARAMETER_TYPE_DESCRIPTOR_TABLE;rp[1].DescriptorTable={1,&range};rp[1].ShaderVisibility=D3D12_SHADER_VISIBILITY_ALL;
  D3D12_ROOT_SIGNATURE_DESC rs{};rs.NumParameters=2;rs.pParameters=rp;rs.Flags=D3D12_ROOT_SIGNATURE_FLAG_NONE;ComPtr<ID3DBlob> blob,err;HRESULT h=D3D12SerializeRootSignature(&rs,D3D_ROOT_SIGNATURE_VERSION_1,&blob,&err);if(FAILED(h)){if(err)fprintf(stderr,"Root signature: %s\n",(char*)err->GetBufferPointer());check(h,"Serialize root signature");}check(dev->CreateRootSignature(0,blob->GetBufferPointer(),blob->GetBufferSize(),IID_PPV_ARGS(&root)),"Create root signature");D3D12_COMPUTE_PIPELINE_STATE_DESC pd{};pd.pRootSignature=root.Get();pd.CS={shader->GetBufferPointer(),shader->GetBufferSize()};check(dev->CreateComputePipelineState(&pd,IID_PPV_ARGS(&pso)),"Create compute PSO");
  D3D12_DESCRIPTOR_HEAP_DESC dh{};dh.Type=D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV;dh.NumDescriptors=1;dh.Flags=D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE;check(dev->CreateDescriptorHeap(&dh,IID_PPV_ARGS(&uavHeap)),"Create UAV heap");descInc=dev->GetDescriptorHandleIncrementSize(D3D12_DESCRIPTOR_HEAP_TYPE_CBV_SRV_UAV);
  D3D12_HEAP_PROPERTIES hp{};hp.Type=D3D12_HEAP_TYPE_DEFAULT;hp.CreationNodeMask=1;hp.VisibleNodeMask=1;D3D12_RESOURCE_DESC rd{};rd.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;rd.Width=(UINT64)maxCount*4;rd.Height=1;rd.DepthOrArraySize=1;rd.MipLevels=1;rd.SampleDesc.Count=1;rd.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;rd.Flags=D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;check(dev->CreateCommittedResource(&hp,D3D12_HEAP_FLAG_NONE,&rd,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,nullptr,IID_PPV_ARGS(&output)),"Create local output buffer");D3D12_UNORDERED_ACCESS_VIEW_DESC uv{};uv.ViewDimension=D3D12_UAV_DIMENSION_BUFFER;uv.Format=DXGI_FORMAT_UNKNOWN;uv.Buffer.NumElements=maxCount;uv.Buffer.StructureByteStride=4;dev->CreateUnorderedAccessView(output.Get(),nullptr,&uv,uavHeap->GetCPUDescriptorHandleForHeapStart());
  D3D12_HEAP_PROPERTIES rpHeap{};rpHeap.Type=D3D12_HEAP_TYPE_READBACK;rpHeap.CreationNodeMask=1;rpHeap.VisibleNodeMask=1;rd.Flags=D3D12_RESOURCE_FLAG_NONE;check(dev->CreateCommittedResource(&rpHeap,D3D12_HEAP_FLAG_NONE,&rd,D3D12_RESOURCE_STATE_COPY_DEST,nullptr,IID_PPV_ARGS(&readback)),"Create readback buffer");
 }
 void encode(UINT base,UINT count,UINT seed,UINT iterations){check(alloc->Reset(),"Reset allocator");check(list->Reset(alloc.Get(),pso.Get()),"Reset command list");list->SetComputeRootSignature(root.Get());ID3D12DescriptorHeap* heaps[]={uavHeap.Get()};list->SetDescriptorHeaps(1,heaps);UINT c[4]={base,count,seed,iterations};list->SetComputeRoot32BitConstants(0,4,c,0);list->SetComputeRootDescriptorTable(1,uavHeap->GetGPUDescriptorHandleForHeapStart());list->Dispatch((count+255)/256,1,1);D3D12_RESOURCE_BARRIER b{};b.Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;b.Transition.pResource=output.Get();b.Transition.Subresource=D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;b.Transition.StateBefore=D3D12_RESOURCE_STATE_UNORDERED_ACCESS;b.Transition.StateAfter=D3D12_RESOURCE_STATE_COPY_SOURCE;list->ResourceBarrier(1,&b);list->CopyBufferRegion(readback.Get(),0,output.Get(),0,(UINT64)count*4);std::swap(b.Transition.StateBefore,b.Transition.StateAfter);list->ResourceBarrier(1,&b);check(list->Close(),"Close compute list");}
 UINT64 submit(){ResetEvent(eventHandle);ID3D12CommandList* ls[]={list.Get()};queue->ExecuteCommandLists(1,ls);UINT64 v=++fv;check(queue->Signal(fence.Get(),v),"Signal local fence");check(fence->SetEventOnCompletion(v,eventHandle),"Set local fence event");return v;}
 void wait(){DWORD w=WaitForSingleObject(eventHandle,INFINITE);if(w!=WAIT_OBJECT_0)throw std::runtime_error("WaitForSingleObject failed");}
 void verify(UINT base,UINT count,UINT seed,UINT iterations){static std::map<std::pair<UINT,UINT>,std::vector<uint32_t>> cache;auto& ref=cache[{seed,iterations}];UINT need=base+count;UINT old=(UINT)ref.size();if(old<need){ref.resize(need);for(UINT j=old;j<need;++j)ref[j]=expected(j,seed,iterations);}void* p=nullptr;D3D12_RANGE r{0,(SIZE_T)count*4};check(readback->Map(0,&r,&p),"Map readback");auto*x=(uint32_t*)p;UINT errors=0;for(UINT i=0;i<count;++i){uint32_t e=ref[base+i];if(x[i]!=e){if(errors<4)fprintf(stderr,"GPU%u mismatch at %u got %08X expected %08X\n",index,base+i,x[i],e);++errors;}}D3D12_RANGE wr{0,0};readback->Unmap(0,&wr);if(errors)throw std::runtime_error("GPU result validation failed");}
};
struct SharedTexture { D3D12_RESOURCE_DESC desc{}; ComPtr<ID3D12Heap> srcHeap,dstHeap; ComPtr<ID3D12Resource> srcRes,dstRes; ComPtr<ID3D12Fence> srcFence,dstFence; HANDLE heapHandle=nullptr,fenceHandle=nullptr; UINT64 fenceValue=0; UINT allocationBytes=0; ~SharedTexture(){if(heapHandle)CloseHandle(heapHandle);if(fenceHandle)CloseHandle(fenceHandle);} };
struct Metrics {double wall=0,g0=0,g1=0,sync=0;bool valid=false;};
static void checkAbort(const std::wstring&root){if(GetFileAttributesW((root+L"\\logs\\thermal-stop.flag").c_str())!=INVALID_FILE_ATTRIBUTES)throw std::runtime_error("THERMAL_OR_MEMORY_STOP_REQUESTED");}
static void appendLine(const std::wstring&path,const std::string&line){std::ofstream f(path,std::ios::app);if(!f)throw std::runtime_error("Could not append CSV");f<<line<<"\n";}
static std::string tag(UINT n){return std::to_string(n);}
static Metrics soloRun(Gpu&g,UINT base,UINT count,UINT seed,UINT iters,const std::wstring&root){checkAbort(root);Metrics m;double t=qpc();g.encode(base,count,seed,iters);g.submit();double w=qpc();g.wait();double e=qpc();m.wall=m.g0=(e-t)*1000;m.sync=(e-w)*1000;g.verify(base,count,seed,iters);m.valid=true;return m;}
static Metrics dualSeq(Gpu&a,Gpu&b,UINT na,UINT nb,UINT seed,UINT iters,const std::wstring&root){checkAbort(root);Metrics m;double all=qpc();double t0=qpc();a.encode(0,na,seed,iters);a.submit();double w0=qpc();a.wait();double e0=qpc();m.g0=(e0-t0)*1000;m.sync=(e0-w0)*1000;double t1=qpc();b.encode(na,nb,seed,iters);b.submit();double w1=qpc();b.wait();double e1=qpc();m.g1=(e1-t1)*1000;m.sync+=(e1-w1)*1000;m.wall=(e1-all)*1000;a.verify(0,na,seed,iters);b.verify(na,nb,seed,iters);m.valid=true;return m;}
static Metrics dualParallel(Gpu&a,Gpu&b,UINT na,UINT nb,UINT seed,UINT iters,const std::wstring&root){checkAbort(root);Metrics m;double all=qpc();double t0=qpc();a.encode(0,na,seed,iters);double t1=qpc();b.encode(na,nb,seed,iters);a.submit();b.submit();double waitStart=qpc();HANDLE ev[2]={a.eventHandle,b.eventHandle};bool done[2]={false,false};double end[2]={0,0};while(!done[0]||!done[1]){DWORD w=WaitForMultipleObjects(2,ev,FALSE,INFINITE);if(w<WAIT_OBJECT_0||w>=WAIT_OBJECT_0+2)throw std::runtime_error("WaitForMultipleObjects failed");int k=(int)(w-WAIT_OBJECT_0);if(!done[k]){done[k]=true;end[k]=qpc();ResetEvent(ev[k]);}}double finish=(end[0]>end[1]?end[0]:end[1]);m.wall=(finish-all)*1000;m.g0=(end[0]-t0)*1000;m.g1=(end[1]-t1)*1000;m.sync=(finish-waitStart)*1000;a.verify(0,na,seed,iters);b.verify(na,nb,seed,iters);m.valid=true;return m;}
static void csvHeader(const std::wstring&root,const wchar_t*name,const char*header){std::ofstream f(root+L"\\"+name,std::ios::trunc);if(!f)throw std::runtime_error("Could not create CSV");f<<header<<"\n";}
static void recordCompute(const std::wstring&root,const char*mode,UINT n,UINT pct,UINT rep,bool warm,UINT na,UINT nb,UINT iters,const Metrics&m){char line[768];sprintf_s(line,"%u,%s,%u,%u,%u,%u,%u,%u,%.4f,%.4f,%.4f,%.4f,0,%s",n,mode,pct,rep,warm?1:0,na,nb,iters,m.wall,m.g0,m.g1,m.sync,m.valid?"PASS":"FAIL");appendLine(root+L"\\benchmark.csv",line);}
static SharedTexture makeSharedTexture(Gpu&src,Gpu&dst,UINT count){SharedTexture x;const UINT width=2048,height=(count+width-1)/width;x.desc.Dimension=D3D12_RESOURCE_DIMENSION_TEXTURE2D;x.desc.Width=width;x.desc.Height=height;x.desc.DepthOrArraySize=1;x.desc.MipLevels=1;x.desc.Format=DXGI_FORMAT_R32_UINT;x.desc.SampleDesc.Count=1;x.desc.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;x.desc.Flags=D3D12_RESOURCE_FLAG_ALLOW_CROSS_ADAPTER;auto ai=src.dev->GetResourceAllocationInfo(0,1,&x.desc);if(ai.SizeInBytes==UINT64_MAX||ai.SizeInBytes>UINT_MAX)throw std::runtime_error("Cross texture allocation info invalid");x.allocationBytes=(UINT)ai.SizeInBytes;D3D12_HEAP_DESC hd{};hd.SizeInBytes=ai.SizeInBytes;hd.Alignment=0;hd.Properties.Type=D3D12_HEAP_TYPE_DEFAULT;hd.Properties.CreationNodeMask=1;hd.Properties.VisibleNodeMask=1;hd.Flags=(D3D12_HEAP_FLAGS)(D3D12_HEAP_FLAG_SHARED|D3D12_HEAP_FLAG_SHARED_CROSS_ADAPTER);check(src.dev->CreateHeap(&hd,IID_PPV_ARGS(&x.srcHeap)),"Create CrossAdapter final-result heap");check(src.dev->CreatePlacedResource(x.srcHeap.Get(),0,&x.desc,D3D12_RESOURCE_STATE_COMMON,nullptr,IID_PPV_ARGS(&x.srcRes)),"Create producer CrossAdapter texture");check(src.dev->CreateSharedHandle(x.srcHeap.Get(),nullptr,GENERIC_ALL,nullptr,&x.heapHandle),"Create CrossAdapter heap handle");check(dst.dev->OpenSharedHandle(x.heapHandle,IID_PPV_ARGS(&x.dstHeap)),"Open CrossAdapter heap on result GPU");check(dst.dev->CreatePlacedResource(x.dstHeap.Get(),0,&x.desc,D3D12_RESOURCE_STATE_COMMON,nullptr,IID_PPV_ARGS(&x.dstRes)),"Create receiver CrossAdapter texture");check(src.dev->CreateFence(0,(D3D12_FENCE_FLAGS)(D3D12_FENCE_FLAG_SHARED|D3D12_FENCE_FLAG_SHARED_CROSS_ADAPTER),IID_PPV_ARGS(&x.srcFence)),"Create CrossAdapter fence");check(src.dev->CreateSharedHandle(x.srcFence.Get(),nullptr,GENERIC_ALL,nullptr,&x.fenceHandle),"Create CrossAdapter fence handle");check(dst.dev->OpenSharedHandle(x.fenceHandle,IID_PPV_ARGS(&x.dstFence)),"Open CrossAdapter fence on result GPU");return x;}
struct TransferResult {double ms=0,waitCallMs=0;bool valid=false;};
static TransferResult transferFinal(Gpu&src,Gpu&dst,SharedTexture&sh,UINT base,UINT count,UINT seed,UINT iters,const std::wstring&root){checkAbort(root);TransferResult result;D3D12_PLACED_SUBRESOURCE_FOOTPRINT fp{};fp.Footprint.Format=DXGI_FORMAT_R32_UINT;fp.Footprint.Width=(UINT)sh.desc.Width;fp.Footprint.Height=sh.desc.Height;fp.Footprint.Depth=1;fp.Footprint.RowPitch=fp.Footprint.Width*4;UINT64 total=0;src.dev->GetCopyableFootprints(&sh.desc,0,1,0,&fp,nullptr,nullptr,&total);if((UINT64)count*4>(UINT64)8*1000000*4)throw std::runtime_error("Cross result exceeds allocated readback");
 check(src.alloc->Reset(),"Reset producer allocator for final copy");check(src.list->Reset(src.alloc.Get(),nullptr),"Reset producer list for final copy");D3D12_RESOURCE_BARRIER sb[2]{};sb[0].Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;sb[0].Transition.pResource=src.output.Get();sb[0].Transition.Subresource=D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;sb[0].Transition.StateBefore=D3D12_RESOURCE_STATE_UNORDERED_ACCESS;sb[0].Transition.StateAfter=D3D12_RESOURCE_STATE_COPY_SOURCE;sb[1].Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;sb[1].Transition.pResource=sh.srcRes.Get();sb[1].Transition.Subresource=D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;sb[1].Transition.StateBefore=D3D12_RESOURCE_STATE_COMMON;sb[1].Transition.StateAfter=D3D12_RESOURCE_STATE_COPY_DEST;src.list->ResourceBarrier(2,sb);D3D12_TEXTURE_COPY_LOCATION dstLoc{};dstLoc.pResource=sh.srcRes.Get();dstLoc.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;D3D12_TEXTURE_COPY_LOCATION srcLoc{};srcLoc.pResource=src.output.Get();srcLoc.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;srcLoc.PlacedFootprint=fp;UINT fullRows=count/(UINT)sh.desc.Width,rem=count%(UINT)sh.desc.Width;D3D12_BOX box{};box.left=box.top=box.front=0;box.right=(UINT)sh.desc.Width;box.bottom=fullRows;box.back=1;if(fullRows)src.list->CopyTextureRegion(&dstLoc,0,0,0,&srcLoc,&box);if(rem){D3D12_BOX last{};last.left=0;last.top=fullRows;last.front=0;last.right=rem;last.bottom=fullRows+1;last.back=1;src.list->CopyTextureRegion(&dstLoc,0,fullRows,0,&srcLoc,&last);}sb[0].Transition.StateBefore=D3D12_RESOURCE_STATE_COPY_SOURCE;sb[0].Transition.StateAfter=D3D12_RESOURCE_STATE_UNORDERED_ACCESS;sb[1].Transition.StateBefore=D3D12_RESOURCE_STATE_COPY_DEST;sb[1].Transition.StateAfter=D3D12_RESOURCE_STATE_COMMON;src.list->ResourceBarrier(2,sb);check(src.list->Close(),"Close producer transfer list");
 check(dst.alloc->Reset(),"Reset receiver allocator for final copy");check(dst.list->Reset(dst.alloc.Get(),nullptr),"Reset receiver list for final copy");D3D12_RESOURCE_BARRIER rb{};rb.Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;rb.Transition.pResource=sh.dstRes.Get();rb.Transition.Subresource=D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;rb.Transition.StateBefore=D3D12_RESOURCE_STATE_COMMON;rb.Transition.StateAfter=D3D12_RESOURCE_STATE_COPY_SOURCE;dst.list->ResourceBarrier(1,&rb);D3D12_TEXTURE_COPY_LOCATION rd{};rd.pResource=dst.readback.Get();rd.Type=D3D12_TEXTURE_COPY_TYPE_PLACED_FOOTPRINT;rd.PlacedFootprint=fp;D3D12_TEXTURE_COPY_LOCATION rs{};rs.pResource=sh.dstRes.Get();rs.Type=D3D12_TEXTURE_COPY_TYPE_SUBRESOURCE_INDEX;if(fullRows)dst.list->CopyTextureRegion(&rd,0,0,0,&rs,&box);if(rem){D3D12_BOX last{};last.left=0;last.top=fullRows;last.front=0;last.right=rem;last.bottom=fullRows+1;last.back=1;dst.list->CopyTextureRegion(&rd,0,fullRows,0,&rs,&last);}rb.Transition.StateBefore=D3D12_RESOURCE_STATE_COPY_SOURCE;rb.Transition.StateAfter=D3D12_RESOURCE_STATE_COMMON;dst.list->ResourceBarrier(1,&rb);check(dst.list->Close(),"Close receiver transfer list");
 UINT64 v=++sh.fenceValue;double wt=qpc();check(dst.queue->Wait(sh.dstFence.Get(),v),"Enqueue wait for unsignaled producer fence");result.waitCallMs=(qpc()-wt)*1000;ID3D12CommandList*dl[]={dst.list.Get()};dst.queue->ExecuteCommandLists(1,dl);UINT64 local=++dst.fv;ResetEvent(dst.eventHandle);check(dst.queue->Signal(dst.fence.Get(),local),"Signal final readback completion");check(dst.fence->SetEventOnCompletion(local,dst.eventHandle),"Set receiver event");double t=qpc();ID3D12CommandList*sl[]={src.list.Get()};src.queue->ExecuteCommandLists(1,sl);check(src.queue->Signal(sh.srcFence.Get(),v),"Signal producer CrossAdapter fence");DWORD w=WaitForSingleObject(dst.eventHandle,30000);if(w!=WAIT_OBJECT_0)throw std::runtime_error("Final-result transfer fence timed out");result.ms=(qpc()-t)*1000;dst.verify(base,count,seed,iters);result.valid=true;return result;}
static void recordTransfer(const std::wstring&root,UINT n,UINT pct,UINT count,UINT rep,bool warm,UINT bytes,UINT heapBytes,const TransferResult&r){char line[512];sprintf_s(line,"%u,%u,%u,%u,%u,%u,%u,%.4f,%.4f,%s",n,pct,count,rep,warm?1:0,bytes,heapBytes,r.ms,r.waitCallMs,r.valid?"PASS":"FAIL");appendLine(root+L"\\transfer-benchmark.csv",line);}
static void saveMemory(){MEMORYSTATUSEX ms{};ms.dwLength=sizeof(ms);GlobalMemoryStatusEx(&ms);PROCESS_MEMORY_COUNTERS_EX pm{};pm.cb=sizeof(pm);GetProcessMemoryInfo(GetCurrentProcess(),(PROCESS_MEMORY_COUNTERS*)&pm,sizeof(pm));printf("Memory snapshot: RAM used=%llu MiB/%llu MiB process working set=%llu MiB\n",(unsigned long long)((ms.ullTotalPhys-ms.ullAvailPhys)/1048576),(unsigned long long)(ms.ullTotalPhys/1048576),(unsigned long long)(pm.WorkingSetSize/1048576));}
int wmain(int argc,wchar_t**argv){setvbuf(stdout,nullptr,_IONBF,0);setvbuf(stderr,nullptr,_IONBF,0);std::wstring root=argc>1?argv[1]:L".";try{const UINT iters=8,seed=0x13579BDF,maxN=8000000;const UINT sizes[]={1000000,2000000,4000000,8000000};const UINT ratios[]={50,55,60,65,70};const UINT warmups=5,reps=20;ComPtr<ID3DBlob> shader;check(D3DReadFileToBlob((root+L"\\compute.cso").c_str(),&shader),"Read compute.cso");ComPtr<IDXGIFactory6> factory;check(CreateDXGIFactory2(0,IID_PPV_ARGS(&factory)),"Create DXGI factory");std::vector<ComPtr<IDXGIAdapter1>> nv;for(UINT i=0;;++i){ComPtr<IDXGIAdapter1>a;HRESULT h=factory->EnumAdapters1(i,&a);if(h==DXGI_ERROR_NOT_FOUND)break;check(h,"EnumAdapters1");DXGI_ADAPTER_DESC1 d{};a->GetDesc1(&d);wprintf(L"Adapter %u '%s' LUID=%08X:%08X vendor=%04X device=%04X\n",i,d.Description,d.AdapterLuid.HighPart,d.AdapterLuid.LowPart,d.VendorId,d.DeviceId);if(d.VendorId==0x10DE)nv.push_back(a);}if(nv.size()<2)throw std::runtime_error("Two NVIDIA adapters required");Gpu g0,g1;g0.init(0,nv[0].Get(),shader.Get(),maxN);g1.init(1,nv[1].Get(),shader.Get(),maxN);printf("Created D3D12 compute contexts; elements up to %u, iterations=%u, warmups/config=%u, measured reps/config=%u.\n",maxN,iters,warmups,reps);
 csvHeader(root,L"benchmark.csv","elements,mode,gpu970_share_percent,rep,warmup,gpu970_elements,gpu750_elements,shader_iterations,total_ms,gpu970_ms,gpu750_ms,sync_wait_ms,transfer_ms,validation");csvHeader(root,L"transfer-benchmark.csv","elements,gpu970_share_percent,gpu750_elements,rep,warmup,transfer_payload_bytes,shared_heap_bytes,transfer_ms,queue_wait_enqueue_ms,validation");
 const bool preflight=argc>2&&_wcsicmp(argv[2],L"--preflight")==0;if(preflight){const UINT n=maxN,p=60,na=n*p/100,nb=n-na;auto m=dualParallel(g0,g1,na,nb,seed,iters,root);printf("PREFLIGHT compute %u 60/40 %.3f ms valid=%d\n",n,m.wall,m.valid);g1.encode(na,nb,seed,iters);g1.submit();g1.wait();g1.verify(na,nb,seed,iters);auto sh=makeSharedTexture(g1,g0,nb);auto tr=transferFinal(g1,g0,sh,na,nb,seed,iters,root);printf("PREFLIGHT transfer %u bytes %.3f ms valid=%d alloc=%u\n",nb*4,tr.ms,tr.valid,sh.allocationBytes);puts("PREFLIGHT_RESULT=PASS");return 0;}
 // Five full-size warmups for each size/mode/ratio.
 for(UINT n:sizes){for(UINT k=0;k<warmups;++k){checkAbort(root);auto a=soloRun(g0,0,n,seed,iters,root);recordCompute(root,"gtx970_solo",n,100,k+1,true,n,0,iters,a);auto b=soloRun(g1,0,n,seed,iters,root);recordCompute(root,"gtx750_solo",n,0,k+1,true,0,n,iters,b);}
  for(UINT pct:ratios){UINT na=n*pct/100,nb=n-na;for(UINT k=0;k<warmups;++k){checkAbort(root);auto s=dualSeq(g0,g1,na,nb,seed,iters,root);recordCompute(root,"dual_sequential",n,pct,k+1,true,na,nb,iters,s);auto p=dualParallel(g0,g1,na,nb,seed,iters,root);recordCompute(root,"dual_parallel",n,pct,k+1,true,na,nb,iters,p);}printf("Warmups complete: N=%u ratio=%u/ %u (dual modes)\n",n,pct,100-pct);}printf("Warmups complete for N=%u\n",n);}
 // Measured configurations, each with exactly 20 validated repetitions.
 for(UINT n:sizes){for(UINT r=1;r<=reps;++r){checkAbort(root);auto m=soloRun(g0,0,n,seed,iters,root);recordCompute(root,"gtx970_solo",n,100,r,false,n,0,iters,m);if(r==1||r%5==0)printf("Measured GTX970 solo N=%u rep=%u/20 %.3f ms\n",n,r,m.wall);}for(UINT r=1;r<=reps;++r){checkAbort(root);auto m=soloRun(g1,0,n,seed,iters,root);recordCompute(root,"gtx750_solo",n,0,r,false,0,n,iters,m);if(r==1||r%5==0)printf("Measured GTX750 solo N=%u rep=%u/20 %.3f ms\n",n,r,m.wall);}
  for(UINT pct:ratios){UINT na=n*pct/100,nb=n-na;for(UINT r=1;r<=reps;++r){checkAbort(root);auto m=dualSeq(g0,g1,na,nb,seed,iters,root);recordCompute(root,"dual_sequential",n,pct,r,false,na,nb,iters,m);if(r==1||r%5==0)printf("Measured sequential N=%u ratio=%u/%u rep=%u/20 %.3f ms\n",n,pct,100-pct,r,m.wall);}for(UINT r=1;r<=reps;++r){checkAbort(root);auto m=dualParallel(g0,g1,na,nb,seed,iters,root);recordCompute(root,"dual_parallel",n,pct,r,false,na,nb,iters,m);if(r==1||r%5==0)printf("Measured parallel N=%u ratio=%u/%u rep=%u/20 %.3f ms\n",n,pct,100-pct,r,m.wall);}}
 }
 puts("COMPUTE_GRID_RESULT=PASS");
 // Final-results-only strategy: precompute the secondary segment, then transfer it once to the primary adapter per sample.
 for(UINT n:sizes)for(UINT pct:ratios){checkAbort(root);UINT na=n*pct/100,nb=n-na;g1.encode(na,nb,seed,iters);g1.submit();g1.wait();g1.verify(na,nb,seed,iters);auto sh=makeSharedTexture(g1,g0,nb);for(UINT k=1;k<=warmups;++k){auto tr=transferFinal(g1,g0,sh,na,nb,seed,iters,root);recordTransfer(root,n,pct,nb,k,true,nb*4,sh.allocationBytes,tr);}printf("Transfer warmups complete N=%u ratio=%u/%u payload=%u bytes\n",n,pct,100-pct,nb*4);for(UINT r=1;r<=reps;++r){checkAbort(root);auto tr=transferFinal(g1,g0,sh,na,nb,seed,iters,root);recordTransfer(root,n,pct,nb,r,false,nb*4,sh.allocationBytes,tr);if(r==1||r%5==0)printf("Measured final-only transfer N=%u ratio=%u/%u rep=%u/20 bytes=%u %.3f ms\n",n,pct,100-pct,nb*4,r,tr.ms);} }
 puts("TRANSFER_GRID_RESULT=PASS");saveMemory();puts("SUITE_RESULT=PASS");return 0;
 }catch(const std::exception&e){fprintf(stderr,"FATAL: %s\n",e.what());if(strstr(e.what(),"THERMAL_OR_MEMORY_STOP_REQUESTED")){puts("SUITE_RESULT=STOPPED_THERMAL_OR_MEMORY");return 3;}puts("SUITE_RESULT=FAIL");return 2;}}






